	'messages:apihelp-query+watchlist-example-simple' => 'en:List the top revision for recently changed pages on the current user\'s watchlist.',
	'messages:apihelp-query+watchlist-example-props' => 'en:Fetch additional information about the top revision for recently changed pages on the current user\'s watchlist.',
	'messages:apihelp-query+watchlist-example-expiry' => 'en:Fetch additional information about the top revision for recently changed pages on the current user\'s watchlist, including when temporarily watched items will expire.',
